/**
 * Business logic for Tempo worklog queries and reports.
 *
 * Tempo v4 answers in numeric ids only, so every query is really two:
 * Tempo for the worklogs, then Jira to turn issue ids into keys and account
 * ids into names. This class owns that join, the filter resolution in the
 * other direction (key to id before asking Tempo), and the aggregation.
 *
 * Nothing here is cached. A report is a question about a date range and the
 * answer changes whenever anybody logs time, so a stale copy has no value.
 *
 * @module
 */

import { JiraConnectionError } from '@softspark/atlassian-mcp-core';

import type { JiraConnector } from '../connector/jira-connector.js';
import type { TempoClient } from '../connector/tempo-client.js';
import type { TempoWorklog, TempoWorklogQuery } from '../connector/tempo-types.js';
import type { JiraIssueRef, JiraUser } from '../connector/types.js';
import { formatTimeSpent } from '../connector/time-parser.js';
import type {
  TempoGroupKey,
  TempoReport,
  TempoReportRow,
  TempoUserRef,
  TempoWorklogEntry,
  TempoWorklogFilter,
} from './types.js';
import { TEMPO_GROUP_KEYS } from './types.js';

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

const ISO_DATE_RE = /^\d{4}-\d{2}-\d{2}$/;

const SECONDS_PER_HOUR = 3600;

// ---------------------------------------------------------------------------
// Internal types
// ---------------------------------------------------------------------------

/** The filter with its keys resolved to the ids Tempo understands. */
interface ResolvedScope {
  readonly projectKey?: string;
  readonly projectId?: string;
  readonly issueKey?: string;
  readonly issueId?: string;
  readonly accountId?: string;
}

interface MutableReportRow {
  project?: string;
  user?: string;
  userEmail?: string | null;
  task?: string;
  summary?: string;
  timeSpentSeconds: number;
  billableSeconds: number;
  worklogCount: number;
}

// ---------------------------------------------------------------------------
// Validation
// ---------------------------------------------------------------------------

/**
 * Reject anything that is not a real `YYYY-MM-DD` range.
 *
 * Tempo answers a malformed date with a 400 whose body is not always
 * helpful, and an inverted range with an empty result that looks like
 * "nobody logged anything". Both are cheaper to catch here.
 */
function assertDateRange(from: string, to: string): void {
  for (const [label, value] of [
    ['from', from],
    ['to', to],
  ] as const) {
    if (!ISO_DATE_RE.test(value) || Number.isNaN(Date.parse(value))) {
      throw new Error(
        `Invalid '${label}' date: '${value}'. Use YYYY-MM-DD.`,
      );
    }
  }
  if (from > to) {
    throw new Error(
      `Invalid date range: 'from' (${from}) is after 'to' (${to}).`,
    );
  }
}

/** Check a `group_by` list before any network call is made. */
export function assertGroupBy(
  groupBy: readonly string[],
): asserts groupBy is readonly TempoGroupKey[] {
  if (groupBy.length === 0) {
    throw new Error(
      `group_by must name at least one of: ${TEMPO_GROUP_KEYS.join(', ')}`,
    );
  }
  const seen = new Set<string>();
  for (const key of groupBy) {
    if (!(TEMPO_GROUP_KEYS as readonly string[]).includes(key)) {
      throw new Error(
        `Unknown group_by value '${key}'. Use: ${TEMPO_GROUP_KEYS.join(', ')}`,
      );
    }
    if (seen.has(key)) {
      throw new Error(`group_by lists '${key}' twice.`);
    }
    seen.add(key);
  }
}

/** Decimal hours with two places, the shape a spreadsheet sums. */
function toHours(seconds: number): number {
  return Math.round((seconds / SECONDS_PER_HOUR) * 100) / 100;
}

// ---------------------------------------------------------------------------
// TempoOperations
// ---------------------------------------------------------------------------

export class TempoOperations {
  constructor(
    private readonly tempo: TempoClient,
    private readonly jira: JiraConnector,
  ) {}

  // -----------------------------------------------------------------------
  // Worklogs
  // -----------------------------------------------------------------------

  /**
   * Every worklog in the range, resolved to keys and names.
   *
   * Filters are pushed down to Tempo where its endpoints allow (issue and
   * project ids on `worklogs`, author on `worklogs/user`) and applied again
   * after enrichment, because the per-user endpoint takes no other filter.
   * Applying them twice costs nothing and keeps the result the same
   * whichever endpoint answered.
   *
   * @throws {Error} On a malformed date range or a task key outside the
   *   given project.
   * @throws {JiraConnectionError} When a filter names an issue or user Jira
   *   cannot find.
   */
  async searchWorklogs(
    filter: TempoWorklogFilter,
  ): Promise<TempoWorklogEntry[]> {
    assertDateRange(filter.from, filter.to);

    const scope = await this.#resolveScope(filter);
    const raw = await this.tempo.getWorklogs(
      TempoOperations.#toQuery(filter, scope),
    );
    const entries = await this.#enrich(raw);

    return entries.filter(
      (entry) =>
        (scope.projectKey === undefined ||
          entry.projectKey === scope.projectKey) &&
        (scope.issueKey === undefined || entry.taskKey === scope.issueKey),
    );
  }

  // -----------------------------------------------------------------------
  // Reports
  // -----------------------------------------------------------------------

  /**
   * Sum the range's worklogs by one or more dimensions.
   *
   * Rows come back largest first, then by key for a stable order between
   * two runs over the same data.
   */
  async report(
    filter: TempoWorklogFilter,
    groupBy: readonly TempoGroupKey[],
  ): Promise<TempoReport> {
    assertGroupBy(groupBy);

    const entries = await this.searchWorklogs(filter);
    const buckets = new Map<string, MutableReportRow>();

    for (const entry of entries) {
      const key = groupBy
        .map((dimension) => TempoOperations.#dimensionKey(entry, dimension))
        .join('�');

      let row = buckets.get(key);
      if (!row) {
        row = TempoOperations.#newRow(entry, groupBy);
        buckets.set(key, row);
      }
      row.timeSpentSeconds += entry.timeSpentSeconds;
      row.billableSeconds += entry.billableSeconds;
      row.worklogCount += 1;
    }

    const rows: TempoReportRow[] = [...buckets.entries()]
      .sort(([keyA, a], [keyB, b]) =>
        b.timeSpentSeconds - a.timeSpentSeconds || keyA.localeCompare(keyB),
      )
      .map(([, row]) => ({
        ...row,
        timeSpent: formatTimeSpent(row.timeSpentSeconds),
        hours: toHours(row.timeSpentSeconds),
      }));

    const totalSeconds = entries.reduce(
      (sum, e) => sum + e.timeSpentSeconds,
      0,
    );
    const billableSeconds = entries.reduce(
      (sum, e) => sum + e.billableSeconds,
      0,
    );

    return {
      from: filter.from,
      to: filter.to,
      groupBy,
      totalSeconds,
      totalTimeSpent: formatTimeSpent(totalSeconds),
      totalHours: toHours(totalSeconds),
      billableSeconds,
      worklogCount: entries.length,
      rows,
    };
  }

  // -----------------------------------------------------------------------
  // Internal: filter resolution
  // -----------------------------------------------------------------------

  /**
   * Turn keys and emails into the ids Tempo filters by.
   *
   * A task key implies its project, so with both given the project is only
   * checked for consistency and never looked up: the issue id alone is the
   * tighter filter.
   */
  async #resolveScope(filter: TempoWorklogFilter): Promise<ResolvedScope> {
    let scope: ResolvedScope = {};

    if (filter.taskKey !== undefined) {
      if (
        filter.projectKey !== undefined &&
        !filter.taskKey.startsWith(`${filter.projectKey}-`)
      ) {
        throw new Error(
          `Task '${filter.taskKey}' does not belong to project '${filter.projectKey}'.`,
        );
      }
      const [ref] = await this.jira.getIssuesByIdsOrKeys([filter.taskKey]);
      if (!ref) {
        throw new JiraConnectionError(
          `Issue not found: ${filter.taskKey}`,
        );
      }
      scope = { ...scope, issueKey: ref.key, issueId: ref.id };
    } else if (filter.projectKey !== undefined) {
      const project = await this.jira.getProject(filter.projectKey);
      scope = { ...scope, projectKey: project.key, projectId: project.id };
    }

    if (filter.userEmail !== undefined) {
      const accountId = await this.jira.findUser(filter.userEmail);
      scope = { ...scope, accountId };
    }

    return scope;
  }

  static #toQuery(
    filter: TempoWorklogFilter,
    scope: ResolvedScope,
  ): TempoWorklogQuery {
    return {
      from: filter.from,
      to: filter.to,
      ...(scope.issueId !== undefined ? { issueIds: [scope.issueId] } : {}),
      ...(scope.projectId !== undefined
        ? { projectIds: [scope.projectId] }
        : {}),
      ...(scope.accountId !== undefined
        ? { authorAccountId: scope.accountId }
        : {}),
    };
  }

  // -----------------------------------------------------------------------
  // Internal: enrichment
  // -----------------------------------------------------------------------

  /**
   * Attach issue keys, summaries and user names to raw Tempo worklogs.
   *
   * Two Jira round trips per query, each chunked by the connector, however
   * many worklogs came back. An issue Jira will not return (deleted, or
   * outside the token's browse permission) keeps its numeric id as
   * `#<id>` so the hours still count instead of vanishing from a total.
   */
  async #enrich(raw: readonly TempoWorklog[]): Promise<TempoWorklogEntry[]> {
    const issueIds = [...new Set(raw.map((w) => w.issueId).filter(Boolean))];
    const accountIds = [
      ...new Set(raw.map((w) => w.authorAccountId).filter(Boolean)),
    ];

    const [issues, users] = await Promise.all([
      issueIds.length > 0
        ? this.jira.getIssuesByIdsOrKeys(issueIds)
        : Promise.resolve<JiraIssueRef[]>([]),
      accountIds.length > 0
        ? this.jira.getUsersByAccountIds(accountIds)
        : Promise.resolve<JiraUser[]>([]),
    ]);

    const issueById = new Map(issues.map((i) => [i.id, i] as const));
    const userById = new Map(users.map((u) => [u.accountId, u] as const));

    return raw.map((w): TempoWorklogEntry => {
      const issue = issueById.get(w.issueId);
      const user = userById.get(w.authorAccountId);
      const userRef: TempoUserRef = user
        ? {
            accountId: user.accountId,
            displayName: user.displayName,
            email: user.emailAddress,
          }
        : { accountId: w.authorAccountId, displayName: w.authorAccountId, email: null };

      return {
        worklogId: w.id,
        taskKey: issue?.key ?? `#${w.issueId}`,
        summary: issue?.summary ?? '(issue not visible)',
        projectKey: issue?.projectKey ?? '',
        user: userRef,
        date: w.startDate,
        startTime: w.startTime,
        timeSpentSeconds: w.timeSpentSeconds,
        timeSpent: formatTimeSpent(w.timeSpentSeconds),
        billableSeconds: w.billableSeconds,
        description: w.description,
      };
    });
  }

  // -----------------------------------------------------------------------
  // Internal: aggregation
  // -----------------------------------------------------------------------

  static #dimensionKey(
    entry: TempoWorklogEntry,
    dimension: TempoGroupKey,
  ): string {
    switch (dimension) {
      case 'project':
        return entry.projectKey;
      case 'user':
        return entry.user.accountId;
      case 'task':
        return entry.taskKey;
    }
  }

  static #newRow(
    entry: TempoWorklogEntry,
    groupBy: readonly TempoGroupKey[],
  ): MutableReportRow {
    const row: MutableReportRow = {
      timeSpentSeconds: 0,
      billableSeconds: 0,
      worklogCount: 0,
    };
    if (groupBy.includes('project')) {
      row.project = entry.projectKey;
    }
    if (groupBy.includes('user')) {
      row.user = entry.user.displayName;
      row.userEmail = entry.user.email;
    }
    if (groupBy.includes('task')) {
      row.task = entry.taskKey;
      row.summary = entry.summary;
    }
    return row;
  }
}
